"use client";

import { Fragment, useMemo, useState } from "react";

import { groupStatuses, type StatusOption } from "@rhs-ui/application/status-select/kinds";
import { StatusMarker } from "@rhs-ui/application/status-select/marker";
import { Kbd } from "@rhs-ui/primitives/kbd";
import { Select, SelectContent, SelectGroup, SelectItem, SelectLabel, SelectSeparator, SelectTrigger, SelectValue, type SelectTriggerProps } from "@rhs-ui/primitives/select";
import { cn } from "@/lib/utils";

export type { StatusKind, StatusOption } from "@rhs-ui/application/status-select/kinds";
export { StatusMarker, type StatusMarkerProps } from "@rhs-ui/application/status-select/marker";

export interface StatusSelectProps extends Omit<SelectTriggerProps, "value" | "defaultValue" | "onChange" | "children" | "size"> {
  /** The options, in order. Give each a `kind` for its marker and, to group them, a `group`. */
  statuses: readonly StatusOption[];
  /** The chosen status, when you control the select. */
  value?: string;
  /** The status to begin with, when the select keeps it itself. */
  defaultValue?: string;
  /** Called with the `value` of the status that was chosen. */
  onValueChange?: (value: string) => void;
  /** `sm` is the compact trigger, 32px with 13px type, for a table cell or a detail panel. Default `default`, 36px. */
  size?: "sm" | "default";
  /** `outline` is a field with a border. `ghost` has none until you hover or open it, so a column of them reads as a list. Default `outline`. */
  variant?: "outline" | "ghost";
  /** Show a number beside each of the first nine options and let the number keys pick them while the list is open. */
  showShortcuts?: boolean;
  /** Shown while nothing is chosen. Default "Set status". */
  placeholder?: string;
  /** The field's name for a plain form submit: the `value` of the chosen status. */
  name?: string;
  /** Turn the select off. */
  disabled?: boolean;
  /** An answer is needed before a form submits. */
  required?: boolean;
}

/**
 * Pick a status, a stage or a priority where the shape tells the state and the
 * colour does not: every option has a small marker (a ring, a half ring, a
 * check, a cross) and a word, in monochrome, so a column of them reads for
 * people who do not see colour. The list is the house Select, with quiet
 * headings for groups such as Open and Closed, arrow keys, Home and End, and
 * typeahead on the words; with `showShortcuts` the number keys pick an option
 * while the list is open. The trigger shows only the marker and the word, so
 * it fits a table cell or a detail panel, and a screen reader hears the
 * chosen status with its group ("In progress, Open"). Pass `marker` on an
 * option for a drawing of your own.
 */
export function StatusSelect({ statuses, value, defaultValue, onValueChange, size = "default", variant = "outline", showShortcuts = false, placeholder = "Set status", name, disabled, required, className, ...props }: StatusSelectProps) {
  const [own, setOwn] = useState(defaultValue ?? "");
  const [open, setOpen] = useState(false);
  const current = value ?? own;
  const groups = useMemo(() => groupStatuses(statuses), [statuses]);
  const flat = groups.flatMap((group) => group.options.map((entry) => ({ ...entry, group: group.name })));
  const selected = flat.find((entry) => entry.option.value === current);

  function pick(next: string) {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  }

  const marker = (option: StatusOption) => option.marker ?? <StatusMarker kind={option.kind ?? "todo"} />;

  return (
    <Select value={current} onValueChange={pick} open={open} onOpenChange={setOpen} name={name} disabled={disabled} required={required}>
      <SelectTrigger
        size={size}
        data-slot="status-select"
        data-variant={variant}
        className={cn(variant === "ghost" && "w-fit border-transparent bg-transparent shadow-none hover:bg-muted data-[state=open]:bg-muted", className)}
        {...props}
      >
        <SelectValue placeholder={placeholder}>
          {selected ? (
            <>
              {marker(selected.option)}
              <span className="truncate">{selected.option.label}</span>
              {/* The group is part of what the status means (in progress is open work), so a screen reader hears it with the word. */}
              {selected.group ? <span className="sr-only">, {selected.group}</span> : null}
            </>
          ) : null}
        </SelectValue>
      </SelectTrigger>
      <SelectContent
        align="start"
        className="min-w-56"
        onKeyDown={(event) => {
          if (!showShortcuts || event.metaKey || event.ctrlKey || event.altKey) return;
          const entry = flat.find((candidate) => String(candidate.shortcut) === event.key && candidate.shortcut <= 9);
          if (!entry) return;
          event.preventDefault();
          pick(entry.option.value);
          setOpen(false);
        }}
      >
        {groups.map((group, index) => (
          <Fragment key={group.name ?? "ungrouped"}>
            {index > 0 ? <SelectSeparator /> : null}
            <SelectGroup>
              {group.name ? <SelectLabel>{group.name}</SelectLabel> : null}
              {group.options.map(({ option, shortcut }) => (
                <SelectItem key={option.value} value={option.value} textValue={option.label} aria-keyshortcuts={showShortcuts && shortcut <= 9 ? String(shortcut) : undefined} className="py-1.5">
                  <span className="flex items-center gap-2.5">
                    {marker(option)}
                    {option.label}
                  </span>
                  {showShortcuts && shortcut <= 9 ? (
                    <Kbd aria-hidden="true" className="absolute top-1/2 right-8 -translate-y-1/2">
                      {shortcut}
                    </Kbd>
                  ) : null}
                </SelectItem>
              ))}
            </SelectGroup>
          </Fragment>
        ))}
      </SelectContent>
    </Select>
  );
}

import type { ReactNode } from "react";

/**
 * The shape of a status. The six shapes differ in drawing as well as weight,
 * so they tell the states apart without colour: a dashed ring, a ring, a
 * half-filled ring, a ring filled three quarters, a solid disc with a check
 * and a ring with a cross.
 */
export type StatusKind = "backlog" | "todo" | "progress" | "review" | "done" | "cancelled";

/** The six kinds, from not started to finished, for a legend or a test. */
export const STATUS_KINDS: readonly StatusKind[] = ["backlog", "todo", "progress", "review", "done", "cancelled"];

export interface StatusOption {
  /** What the select reports when this one is chosen. */
  value: string;
  /** The word beside the marker. */
  label: string;
  /** Which marker is drawn. Leave it out when you pass a `marker` of your own. */
  kind?: StatusKind;
  /** The quiet heading the option sits under, such as "Open" or "Closed". Options with the same group are listed together, in the order the groups first appear. */
  group?: string;
  /** A marker of your own, drawn instead of the one for `kind`: priority bars, a stage number. It should be 16px, decorative and drawn in `currentColor`. */
  marker?: ReactNode;
}

export interface StatusGroup {
  /** The heading, or undefined for options that have no group. */
  name: string | undefined;
  options: { option: StatusOption; shortcut: number }[];
}

/** The options gathered under their groups, each with the number key that picks it: 1 for the first in the list, 2 for the next. */
export function groupStatuses(statuses: readonly StatusOption[]): StatusGroup[] {
  const groups: StatusGroup[] = [];
  for (const option of statuses) {
    let group = groups.find((candidate) => candidate.name === option.group);
    if (!group) {
      group = { name: option.group, options: [] };
      groups.push(group);
    }
    group.options.push({ option, shortcut: 0 });
  }
  let number = 0;
  for (const group of groups) for (const entry of group.options) entry.shortcut = ++number;
  return groups;
}

"use client";

import { useId, type ComponentProps } from "react";

import type { StatusKind } from "@rhs-ui/application/status-select/kinds";
import { cn } from "@/lib/utils";

/** The kinds that are drawn in the quiet ink: not started yet, or set aside. */
const QUIET: ReadonlySet<StatusKind> = new Set(["backlog", "todo", "cancelled"]);

export interface StatusMarkerProps extends Omit<ComponentProps<"svg">, "children"> {
  /** Which marker to draw. */
  kind: StatusKind;
  /** Width and height in px. Default 16. It is drawn on a 16 unit grid and was checked at 14, 16, 20 and 24. */
  size?: number;
}

/**
 * The marker of a status, on a 16 unit grid: a dashed ring for backlog, a ring
 * for to do, a ring half filled for in progress and three quarters for in
 * review, a solid disc with the check cut out of it for done, and a ring with a
 * cross for cancelled. The check is cut with a mask, so whatever is behind the
 * marker shows through it, on a hovered row as on the page. It draws in
 * `currentColor` and is hidden from assistive technology: put the word next to it.
 */
export function StatusMarker({ kind, size = 16, className, style, ...props }: StatusMarkerProps) {
  const mask = useId().replace(/[^\w-]/g, "");
  return (
    <svg
      data-slot="status-marker"
      data-kind={kind}
      viewBox="0 0 16 16"
      fill="none"
      aria-hidden="true"
      focusable="false"
      style={{ width: size, height: size, ...style }}
      className={cn("shrink-0", QUIET.has(kind) ? "text-muted-foreground" : "text-foreground", className)}
      {...props}
    >
      {kind === "done" ? (
        <>
          <mask id={mask} maskUnits="userSpaceOnUse" x="0" y="0" width="16" height="16">
            <rect width="16" height="16" fill="white" />
            <path d="M5.1 8.2l2 2 3.8-4.2" stroke="black" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
          </mask>
          <circle cx="8" cy="8" r="7" fill="currentColor" mask={`url(#${mask})`} />
        </>
      ) : (
        <>
          <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" strokeDasharray={kind === "backlog" ? "1.9 2.03" : undefined} />
          {kind === "progress" ? <path d="M8 4.5a3.5 3.5 0 0 1 0 7z" fill="currentColor" /> : null}
          {kind === "review" ? <path d="M8 8V4.5A3.5 3.5 0 1 1 4.5 8z" fill="currentColor" /> : null}
          {kind === "cancelled" ? <path d="M5.9 5.9l4.2 4.2M10.1 5.9l-4.2 4.2" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" /> : null}
        </>
      )}
    </svg>
  );
}
